import { Card } from "./Card";

const usd = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2 });

function Row({ label, value }: { label: string; value: number }) {
  return (
    <div className="flex justify-between">
      <dt>{label}</dt>
      <dd className="tabular-nums">{usd.format(value)}</dd>
    </div>
  );
}

export function PriceBreakdown({
  nightlyRate,
  nights,
  cleaningFee = 0,
  taxes = 0,
}: {
  nightlyRate: number;
  nights: number;
  cleaningFee?: number;
  taxes?: number;
}) {
  const subtotal = nightlyRate * nights;
  const total = subtotal + cleaningFee + taxes;

  return (
    <Card
      title="Price details"
      footer={
        <dl className="flex justify-between text-base font-semibold text-slate-900">
          <dt>Total</dt>
          <dd className="tabular-nums">{usd.format(total)}</dd>
        </dl>
      }
    >
      <dl className="space-y-2">
        <Row label={`${usd.format(nightlyRate)} x ${nights} ${nights === 1 ? "night" : "nights"}`} value={subtotal} />
        {cleaningFee > 0 && <Row label="Cleaning fee" value={cleaningFee} />}
        {taxes > 0 && <Row label="Taxes" value={taxes} />}
      </dl>
    </Card>
  );
}

